def transform(grid):
    h, w = len(grid), len(grid[0])

    sep_rows = [r for r in range(h) if all(x == 8 for x in grid[r])]
    sep_cols = [c for c in range(w) if all(grid[r][c] == 8 for r in range(h))]

    def bands(n, separators):
        edges = [-1] + separators + [n]
        return [(edges[i] + 1, edges[i + 1]) for i in range(len(edges) - 1)]

    rb, cb = bands(h, sep_rows), bands(w, sep_cols)

    # Ignore any incomplete border bands.
    from collections import Counter
    rh = Counter(b - a for a, b in rb).most_common(1)[0][0]
    cw = Counter(b - a for a, b in cb).most_common(1)[0][0]
    rb = [(a, b) for a, b in rb if b - a == rh]
    cb = [(a, b) for a, b in cb if b - a == cw]

    points = {2: [], 3: []}
    for i, (r0, r1) in enumerate(rb):
        for j, (c0, c1) in enumerate(cb):
            for color in points:
                if any(grid[r][c] == color
                       for r in range(r0, r1) for c in range(c0, c1)):
                    points[color].append((i, j))

    painted = {}
    for color, pts in points.items():
        for a in range(len(pts)):
            r1, c1 = pts[a]
            for b in range(a + 1, len(pts)):
                r2, c2 = pts[b]
                if r1 == r2:
                    for c in range(min(c1, c2), max(c1, c2) + 1):
                        painted[(r1, c)] = color
                elif c1 == c2:
                    for r in range(min(r1, r2), max(r1, r2) + 1):
                        painted[(r, c1)] = color

    out = [row[:] for row in grid]
    for (i, j), color in painted.items():
        r0, r1 = rb[i]
        c0, c1 = cb[j]
        for r in range(r0, r1):
            for c in range(c0, c1):
                if (i, j) in painted and any(
                    other != color and (i, j) in cells
                    for other, cells in []
                ):
                    pass
                out[r][c] = color

    # Crossings of different-color lines are colored 6.
    coverage = {}
    for color, pts in points.items():
        for a in range(len(pts)):
            r1, c1 = pts[a]
            for b in range(a + 1, len(pts)):
                r2, c2 = pts[b]
                cells = []
                if r1 == r2:
                    cells = [(r1, c) for c in range(min(c1, c2), max(c1, c2) + 1)]
                elif c1 == c2:
                    cells = [(r, c1) for r in range(min(r1, r2), max(r1, r2) + 1)]
                for cell in cells:
                    coverage.setdefault(cell, set()).add(color)

    for (i, j), colors in coverage.items():
        color = 6 if len(colors) > 1 else next(iter(colors))
        r0, r1 = rb[i]
        c0, c1 = cb[j]
        for r in range(r0, r1):
            for c in range(c0, c1):
                out[r][c] = color

    return out
